import { useState, useEffect } from "react";
import { X } from "lucide-react";
import { getCategories } from "../../services/categoryService";
import { submitEditRequest } from "../../services/editRequestService";
import {
  isEditRequestFormValid,
  filterCategories,
  resetDetailOnReasonChange,
} from "../../utils/editRequestUtils";
import "./EditRequestModal.css";

/**
 * 수정 요청 사유 입력 모달
 * @param {boolean} isOpen - 모달 표시 여부
 * @param {function} onClose - 모달 닫기 콜백
 * @param {number} complaintId - 민원 ID
 * @param {string} currentCategory - 현재 민원 카테고리 (제외 대상)
 * @param {function} onSuccess - 제출 성공 콜백
 */
const EditRequestModal = ({ isOpen, onClose, complaintId, currentCategory, onSuccess }) => {
  const [reasonType, setReasonType] = useState(null);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [otherReason, setOtherReason] = useState("");
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState(null);

  // 카테고리 관련 상태
  const [categories, setCategories] = useState([]);
  const [categoriesLoading, setCategoriesLoading] = useState(false);
  const [categoriesError, setCategoriesError] = useState(null);

  // 카테고리 변경 요청 선택 시 카테고리 목록 조회
  useEffect(() => {
    if (reasonType === "카테고리 변경 요청") {
      setCategoriesLoading(true);
      setCategoriesError(null);
      getCategories()
        .then((res) => {
          setCategories(res.categories || []);
        })
        .catch(() => {
          setCategoriesError("카테고리 목록을 불러올 수 없습니다.");
        })
        .finally(() => {
          setCategoriesLoading(false);
        });
    }
  }, [reasonType]);

  // 모달이 닫힐 때 상태 초기화
  useEffect(() => {
    if (!isOpen) {
      setReasonType(null);
      setSelectedCategory(null);
      setOtherReason("");
      setSubmitting(false);
      setError(null);
      setCategories([]);
      setCategoriesLoading(false);
      setCategoriesError(null);
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const handleReasonChange = (newReasonType) => {
    const resetState = resetDetailOnReasonChange(reasonType, newReasonType, {
      selectedCategory,
      otherReason,
    });
    setSelectedCategory(resetState.selectedCategory);
    setOtherReason(resetState.otherReason);
    setReasonType(newReasonType);
    setError(null);
  };

  const handleSubmit = async () => {
    if (submitting) return;

    let detail = "";
    if (reasonType === "카테고리 변경 요청") {
      detail = selectedCategory?.category_name || "";
    } else if (reasonType === "기타") {
      detail = otherReason.trim();
    } else if (reasonType === "담당자 변경") {
      detail = "담당자 변경";
    }

    setSubmitting(true);
    setError(null);

    try {
      await submitEditRequest(complaintId, { reasonType, detail });
      onSuccess?.();
    } catch (err) {
      setError(err.message || "수정 요청 제출에 실패했습니다.");
    } finally {
      setSubmitting(false);
    }
  };

  const isFormValid = isEditRequestFormValid(reasonType, selectedCategory, otherReason);
  const filteredCategories = filterCategories(categories, currentCategory);

  const radioOptions = [
    { value: "담당자 변경", label: "담당자 변경" },
    { value: "카테고리 변경 요청", label: "카테고리 변경 요청" },
    { value: "기타", label: "기타" },
  ];

  return (
    <div className="edit-request-overlay" onClick={onClose}>
      <div className="edit-request-modal" onClick={(e) => e.stopPropagation()}>
        <div className="edit-request-header">
          <h3 className="edit-request-title">수정 요청</h3>
          <button className="edit-request-close-btn" onClick={onClose}>
            <X size={20} />
          </button>
        </div>

        <div className="edit-request-body">
          <p className="edit-request-label">수정 요청 사유를 선택해주세요</p>

          <div className="edit-request-radio-group">
            {radioOptions.map((option) => (
              <label key={option.value} className="edit-request-radio-item">
                <input
                  type="radio"
                  name="reasonType"
                  value={option.value}
                  checked={reasonType === option.value}
                  onChange={() => handleReasonChange(option.value)}
                />
                <span className="edit-request-radio-label">{option.label}</span>
              </label>
            ))}
          </div>

          {/* 카테고리 변경 요청 선택 시 드롭다운 */}
          {reasonType === "카테고리 변경 요청" && (
            <div className="edit-request-detail-field">
              {categoriesLoading ? (
                <p className="edit-request-loading">카테고리 목록 로딩 중...</p>
              ) : categoriesError ? (
                <p className="edit-request-error">{categoriesError}</p>
              ) : (
                <select
                  className="edit-request-select"
                  value={selectedCategory?.category_id || ""}
                  onChange={(e) => {
                    const catId = Number(e.target.value);
                    const cat = filteredCategories.find((c) => c.category_id === catId);
                    setSelectedCategory(cat || null);
                  }}
                >
                  <option value="">카테고리 선택</option>
                  {filteredCategories.map((cat) => (
                    <option key={cat.category_id} value={cat.category_id}>
                      {cat.category_name}
                    </option>
                  ))}
                </select>
              )}
            </div>
          )}

          {/* 기타 선택 시 textarea */}
          {reasonType === "기타" && (
            <div className="edit-request-detail-field">
              <textarea
                className="edit-request-textarea"
                placeholder="수정 요청 사유를 입력해주세요 (최대 500자)"
                value={otherReason}
                onChange={(e) => {
                  if (e.target.value.length <= 500) {
                    setOtherReason(e.target.value);
                  }
                }}
                maxLength={500}
              />
              <span className="edit-request-char-count">
                {otherReason.length} / 500
              </span>
            </div>
          )}

          {/* 에러 메시지 */}
          {error && <p className="edit-request-error">{error}</p>}
        </div>

        <div className="edit-request-footer">
          <button
            className="edit-request-submit-btn"
            disabled={!isFormValid || submitting}
            onClick={handleSubmit}
          >
            {submitting ? "제출 중..." : "제출"}
          </button>
        </div>
      </div>
    </div>
  );
};

export default EditRequestModal;
